mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("a=[1,3,7,0,0,0] m=3; b=[2,5,6]","1,2,3,5,6,7"),
        ("a=[2,0] m=1; b=[1]","1,2"),
        ("a=[0,0,0] m=0; b=[1,2,3]","1,2,3"),
        ("a=[1,2,0,0] m=2; b=[1,2]","1,1,2,2"),
        ("a=[9,0] m=1; b=[2]","2,9"),
        ("  \na=[1,3,7,0,0,0] m=3; b=[2,5,6]\n  ","1,2,3,5,6,7"),
        ("\na=[9,0] m=1; b=[2]\n","2,9")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS in-place-merge");
}
